// 原文との一致判定用の正規化（docs/ziwei-basic-spec.md §35）。
// 星名・宮名・占術用語、定型の条件句、意味を持たない汎用の語尾を伏せてから、連続一致を数える。
export const WINDOW = 9;
const NAMES = ["紫微星", "天機星", "太陽星", "武曲星", "天同星", "廉貞星", "天府星", "太陰星", "貪狼星", "巨門星", "天相星", "天梁星",
  "七殺星", "破軍星", "文昌星", "文曲星", "天空星", "地劫星", "火星", "鈴星", "左輔星", "右弼星", "天姚星", "天馬星",
  "禄存星", "擎羊星", "敬羊星", "羊星", "陀羅星", "天魁星", "天鉞星", "紅鸞星", "化禄星", "化権星", "化科星", "化忌星",
  "命宮", "兄弟宮", "夫妻宮", "子女宮", "財帛宮", "疾厄宮", "遷移宮", "奴僕宮", "官禄宮", "田宅宮", "福徳宮", "父母宮", "身宮",
  "三方四正", "運命指数", "力量", "同宮", "加会", "化禄", "化権", "化科", "化忌",
  "紫微", "天機", "太陽", "武曲", "天同", "廉貞", "天府", "太陰", "貪狼", "巨門", "天相", "天梁", "七殺", "破軍",
  "文昌", "文曲", "左輔", "右弼", "天魁", "天鉞", "擎羊", "陀羅", "禄存", "天馬", "地空", "地劫", "三台", "八座", "煞星", "吉星", "凶星"];
const SORTED = [...NAMES].sort((a, b) => b.length - a.length);
const GENERIC = /その限りではありません|の限りではありません|にも適性があります|ことを好みません|ことも好みません|に関心を示します|関心を示します|暗示があるので|暗示もあります|雰囲気を持っています|に富んでいます|ところがあります|こともあります|にも恵まれています|恵まれています|ことが多くなります|が多くなります|が多いようです|ことになります|を身につけます|ていきます|しなければならない|がはっきりしていて|を築きます|に適性があります|が向いています|が望ましいでしょう|ようなこともありません|ことはまずありません|ことはまずあり|ようなこともあり|になることが多い|傾向があります|てしまいます|のもよいでしょう|ことがあります|人もいます|ようになります|暗示があります|必要があります|わけではありません|ことはありませんでした|ことはありません|注意が必要です|少なくありません|ありませんでした|に向いています|こともありました|てしまいました|でもあります|ているようです|を判断します|を読み取ります|しなければなりません|ことができます|ことにします|を見ます|でしょう/g;
export function maskText(t) {
  for (const n of SORTED) t = t.split(n).join("＃");
  t = t.replace(/[、。「」（）・\s]/g, "");
  t = t.replace(/巡る宮の＃が?(強|弱)/g, "＃");
  t = t.replace(/＃(の|と)?(＃|宮威)が?(強|弱)/g, "＃");
  t = t.replace(/＃を＃に持つ|＃に＃を持つ|＃が＃にある|＃に＃がある|＃が＃に入/g, "＃");
  t = t.replace(/＃+/g, "＃");
  return t.replace(GENERIC, "＄");
}
export function fnv(s) {
  let h = 0x811c9dc5;
  for (const c of s) {
    h ^= c.codePointAt(0);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(36);
}
/** 伏せた文字列の9字窓のハッシュ */
export function windows(t) {
  const m = [...maskText(t)];
  const out = [];
  for (let i = 0; i + WINDOW <= m.length; i++) out.push(fnv(m.slice(i, i + WINDOW).join("")));
  return out;
}
